def text_name_allowed(name: str) -> bool:
    folded = name.casefold()
    if folded in ALLOWED_TEXT_BASENAMES:
        return True
    suffix = Path(folded).suffix
    return suffix in ALLOWED_TEXT_EXTENSIONS


def media_name_forbidden(name: str) -> bool:
