OUTLINE_EXPORT_KEYS = ("ok", "status", "message", "schema", "context", "context_sha256", "prompt")
SECTION_EXPORT_KEYS = (
    "ok",
    "status",
    "message",
    "schema",
    "project_id",
    "parent_revision_id",
    "section_id",
